SELECT encode(id, 'hex') AS "id", coupon_code AS "couponCode", name, discount_type AS "discountType", threshold_amount_yuan AS "thresholdAmountYuan", discount_amount_yuan AS "discountAmountYuan", discount_rate AS "discountRate", max_discount_amount_yuan AS "maxDiscountAmountYuan", total_quantity AS "totalQuantity", remaining_quantity AS "remainingQuantity", per_user_limit AS "perUserLimit", scope_type AS "scopeType", receive_start_at AS "receiveStartAt", receive_end_at AS "receiveEndAt", valid_start_at AS "validStartAt", valid_end_at AS "validEndAt", status, version, created_at AS "createdAt", updated_at AS "updatedAt" FROM coupon_template WHERE status != 'DELETED'
AND name ILIKE CONCAT('%', #{name}, '%')
AND status = #{status}
ORDER BY updated_at DESC, created_at DESC LIMIT #{pageSize} OFFSET #{offset}

